<script setup lang="ts">
import { onMounted, ref } from 'vue'
import DashboardNav from '@/components/dashboard/DashboardNav.vue'
import ProductForm from '@/components/dashboard/ProductForm.vue'
import { archiveProduct, deleteProduct, getOwnedMerchant, getProducts, restoreProduct, saveProduct } from '@/lib/api'
import { formatMoney } from '@/lib/format'
import type { Merchant, Product } from '@/types'
const products=ref<Product[]>([]),merchant=ref<Merchant|null>(null),editing=ref<Product|null>(null),showForm=ref(false),error=ref(''),loading=ref(true),saving=ref(false),importing=ref(false)
async function load(){loading.value=true;error.value='';try{merchant.value=await getOwnedMerchant();if(merchant.value)products.value=await getProducts(merchant.value.id,true)}catch(e){error.value=e instanceof Error?e.message:'Products could not be loaded.'}finally{loading.value=false}}
onMounted(load)
async function save(payload:any){if(!merchant.value)return;saving.value=true;error.value='';try{await saveProduct(merchant.value.id,payload,editing.value?.id);showForm.value=false;editing.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:'Product could not be saved.'}finally{saving.value=false}}
function edit(p:Product){editing.value=p;showForm.value=true}
async function archive(p:Product){if(!merchant.value||!confirm(`Hide ${p.name} from the storefront? You can restore it here later.`))return;error.value='';try{await archiveProduct(merchant.value.id,p.id);await load()}catch(e){error.value=e instanceof Error?e.message:'Product could not be archived.'}}
async function restore(p:Product){if(!merchant.value)return;error.value='';try{await restoreProduct(merchant.value.id,p.id);await load()}catch(e){error.value=e instanceof Error?e.message:'Product could not be restored.'}}
async function remove(p:Product){if(!merchant.value||!confirm(`Delete ${p.name}?`))return;error.value='';try{await deleteProduct(merchant.value.id,p.id);await load()}catch(e){error.value=e instanceof Error?e.message:'Product could not be deleted.'}}
function csvRow(line:string){const values:string[]=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'&&quoted&&line[i+1]==='"'){value+='"';i++}else if(char==='"')quoted=!quoted;else if(char===','&&!quoted){values.push(value.trim());value=''}else value+=char}values.push(value.trim());return values}
async function importCsv(file?:File){if(!merchant.value||!file)return;importing.value=true;error.value='';try{const lines=(await file.text()).split(/\r?\n/).filter(line=>line.trim());if(lines.length<2)throw new Error('The CSV needs a header and at least one product row.');const headers=csvRow(lines[0]).map(header=>header.toLowerCase().trim());const required=['name','price','category','primary_image_url','product_url'];const missing=required.filter(header=>!headers.includes(header));if(missing.length)throw new Error(`Missing CSV columns: ${missing.join(', ')}.`);for(const [index,line] of lines.slice(1).entries()){const values=csvRow(line);const row=Object.fromEntries(headers.map((header,column)=>[header,values[column]||'']));try{await saveProduct(merchant.value.id,{name:row.name,description:row.description||'',price:Number(row.price),currency:row.currency||merchant.value.currency||'NGN',category:row.category,style_audience:['menswear','womenswear','unisex'].includes(row.style_audience)?row.style_audience as any:'unisex',primary_image_url:row.primary_image_url,product_url:row.product_url,sizes:(row.sizes||'').split('|').filter(Boolean),colours:(row.colours||'').split('|').filter(Boolean),tags:(row.tags||'').split('|').filter(Boolean),stock_status:['in_stock','low_stock','out_of_stock'].includes(row.stock_status)?row.stock_status as any:'in_stock'})}catch(caught){throw new Error(`Row ${index+2}: ${caught instanceof Error?caught.message:'could not be imported.'}`)}}await load()}catch(caught){error.value=caught instanceof Error?caught.message:'Catalogue import failed.'}finally{importing.value=false}}
</script>
<template><div class="min-h-screen bg-paper lg:flex"><DashboardNav/><main class="flex-1 p-4 sm:p-6 lg:p-9"><div class="mx-auto max-w-6xl"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-[.18em] text-muted">Catalogue</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">Products</h1><p class="mt-2 text-sm text-muted">Manage the catalogue shoppers can discover and try on.</p></div><div class="flex gap-2"><label class="cursor-pointer rounded-full border border-ink px-4 py-3 text-xs font-semibold"><input type="file" accept=".csv,text/csv" class="hidden" @change="importCsv(($event.target as HTMLInputElement).files?.[0])"/>{{importing?'Importing…':'Import CSV'}}</label><button class="min-h-11 rounded-full bg-ink px-4 py-2 text-xs font-semibold text-white disabled:opacity-50" :disabled="loading||!merchant" @click="editing=null;showForm=true">+ Add product</button></div></div><p class="mt-3 text-[10px] leading-4 text-muted">CSV columns: name, price, category, primary_image_url and product_url. Optional collection, sizes, colours and tags use <span class="font-semibold">style_audience</span> and pipe-separated values.</p><div v-if="showForm&&merchant" class="mt-6 rounded-[1.4rem] border border-line bg-white p-5"><h2 class="mb-5 font-semibold">{{editing?'Edit product':'Add product'}}</h2><p v-if="saving" class="mb-3 text-xs text-muted">Saving product…</p><ProductForm :key="editing?.id || 'new'" :merchant-id="merchant.id" :product="editing" :disabled="saving" @save="save" @cancel="showForm=false;editing=null"/></div><p v-if="error" role="alert" class="mt-4 rounded-xl bg-red-50 px-4 py-3 text-xs text-red-700">{{error}}</p><div v-if="loading" class="mt-7 rounded-[1.4rem] border border-line bg-white p-6 text-sm text-muted">Loading catalogue…</div><div v-else-if="!merchant" class="mt-7 rounded-[1.4rem] border border-line bg-white p-6"><h2 class="font-semibold">Catalogue unavailable</h2><p class="mt-2 text-sm text-muted">Sign in with the merchant account that owns this store.</p></div><div v-else-if="products.length" class="mt-7 overflow-hidden rounded-[1.4rem] border border-line bg-white"><div v-for="p in products" :key="p.id" class="flex items-center gap-3 border-b border-line p-3 last:border-0" :class="!p.is_active?'opacity-55':''"><img :src="p.primary_image_url" :alt="p.name" class="h-16 w-14 rounded-lg object-cover"/><div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold">{{p.name}}</p><p class="mt-1 text-xs text-muted">{{p.category}} · {{p.style_audience || 'unisex'}} · {{p.is_active?p.stock_status.replace('_',' '):'hidden'}}</p></div><p class="hidden text-sm font-medium sm:block">{{formatMoney(p.price,p.currency)}}</p><div class="flex gap-1 text-xs"><button class="min-h-10 rounded-lg px-2 hover:bg-paper" @click="edit(p)">Edit</button><button v-if="p.is_active" class="min-h-10 rounded-lg px-2 hover:bg-paper" @click="archive(p)">Hide</button><button v-else class="min-h-10 rounded-lg px-2 hover:bg-paper" @click="restore(p)">Restore</button><button class="min-h-10 rounded-lg px-2 text-red-700 hover:bg-red-50" @click="remove(p)">Delete</button></div></div></div><div v-else class="mt-7 rounded-[1.4rem] border border-dashed border-line bg-white p-8 text-center"><h2 class="font-semibold">Add your first product</h2><p class="mt-2 text-sm text-muted">Your storefront catalogue starts here.</p><button class="mt-5 min-h-11 rounded-full bg-ink px-5 text-xs font-semibold text-white" @click="showForm=true">Add product</button></div></div></main></div></template>
